// ============================================================

// Embedded certificate logos. Keeping the image data inside the JavaScript
// avoids browser/server path issues and prevents Acrobat-invalid image objects.
const EMBEDDED_COLLEGE_LOGO = 'data:image/jpeg;base64,';
const EMBEDDED_PYTHON_LOGO = 'data:image/png;base64,';
// STUDENT DASHBOARD
// Displays the logged-in student information, tests, attendance,
// and public test-score information.
// ============================================================

const session = getSession("studentSession");

if (!session) {
  location.href = "login.html";
} else {
  document.getElementById("studentName").textContent = session.name || "Student";
  document.getElementById("welcomeName").textContent = (session.name || "Student").split(" ")[0];

  document.getElementById("logoutBtn").addEventListener("click", () => {
    clearSession("studentSession");
    location.href = "login.html";
  });

  loadDashboard();
  window.dashboardRefreshTimer = setInterval(() => { loadTopPerformer(); loadCertificateStatus(); }, 60000);
  document.getElementById("downloadPerformanceBtn")?.addEventListener("click", downloadMyPerformance);
  document.getElementById("downloadPerformancePdfBtn")?.addEventListener("click", downloadMyPerformancePdf);
  document.getElementById("downloadCertificateBtn")?.addEventListener("click", downloadCertificate);
  document.getElementById("feedbackForm")?.addEventListener("submit", submitFeedback);
}

function escapeHtml(v) {
  return String(v ?? "").replace(/[&<>"']/g, c => ({
    "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#039;"
  }[c]));
}

function renderProfile(s) {
  const student = s || {};
  const items = [
    ["Name", student.name],
    ["Email", student.email],
    ["Mobile", student.mobile],
    ["SY Roll Number", student.syRoll],
    ["TY Roll Number", student.tyRoll],
    ["Department", student.department],
    ["Year", student.year],
    ["Division", student.division],
    ["College", student.college]
  ];

  document.getElementById("profile").innerHTML = items.map(([k,v]) =>
    `<div><span>${escapeHtml(k)}</span><strong>${escapeHtml(v || "-")}</strong></div>`
  ).join("");
}

async function loadDashboard() {
  // Load each dashboard part separately. If one part has a problem,
  // aptitude tests and attendance can still appear.
  await Promise.all([
    loadStudent(),
    loadTests(),
    loadResults(),
    loadAttendance(),
    loadTopPerformer(),
    loadCertificateStatus()
  ]);
}

async function loadStudent() {
  try {
    const data = await api("getStudent", {email: session.email});
    renderProfile(data.student);
  } catch (err) {
    document.getElementById("profile").innerHTML =
      `<div class="empty error-text">${escapeHtml(err.message)}</div>`;
  }
}

async function loadTests() {
  const box = document.getElementById("tests");
  box.innerHTML = `<div class="loading">Loading aptitude tests…</div>`;

  try {
    const data = await api("getTests", {email: session.email});
    renderTests(data.tests || []);
  } catch (err) {
    box.innerHTML = `<div class="empty error-text">${escapeHtml(err.message)}</div>`;
  }
}

function renderTests(tests) {
  const box = document.getElementById("tests");

  if (!tests.length) {
    box.innerHTML = `<div class="empty">No aptitude tests are available yet.</div>`;
    return;
  }

  box.innerHTML = tests.map(t => `
    <article class="test-card">
      <div class="test-number">${escapeHtml(t.testId)}</div>
      <h3>${escapeHtml(t.testName)}</h3>
      <p>${escapeHtml(t.description || "Aptitude assessment")}</p>
      <div class="test-meta">
        <span>⏱ ${Number(t.duration || 0)} min</span>
        <span>✦ ${Number(t.questionCount || 0)} questions</span>
        <span>★ ${Number(t.maxScore || 0)} marks</span>
      </div>
      ${t.completed
        ? `<button class="btn disabled-btn" disabled>✓ Completed</button>`
        : Number(t.questionCount || 0) === 0
          ? `<button class="btn disabled-btn" disabled>No Questions</button>`
          : `<a class="btn primary" href="aptitude.html?test=${encodeURIComponent(t.testId)}">Start Test</a>`
      }
    </article>
  `).join("");
}


async function loadTopPerformer() {
  const box = document.getElementById("topPerformer");
  try {
    const data = await api("getTopScores");
    const items = (data.topScores || data.leaderboard || []).map(g => ({
      testName:g.testName || "Test",
      studentName:(g.students && g.students[0] ? g.students[0].studentName : "-"),
      score:(g.students && g.students[0] ? g.students[0].score : 0),
      maxScore:(g.students && g.students[0] ? g.students[0].maxScore : "")
    }));
    if (!items.length) { box.innerHTML = '<div class="empty">No test scores are available yet.</div>'; return; }
    box.innerHTML = items.map((x,i)=>`<div class="score-slide ${i===0?'active':''}"><span class="score-rank">HIGHEST SCORE</span><h3>${escapeHtml(x.studentName)}</h3><p>${escapeHtml(x.testName)}</p><strong>${escapeHtml(x.score)}</strong></div>`).join("");
    let index=0;
    clearInterval(window.scoreCarouselTimer);
    const slides=box.querySelectorAll('.score-slide');
    window.scoreCarouselTimer=setInterval(()=>{
      slides[index].classList.remove('active'); index=(index+1)%slides.length; slides[index].classList.add('active');
    },4000);
  } catch(err) { box.innerHTML = `<div class="empty error-text">${escapeHtml(err.message)}</div>`; }
}

async function loadCertificateStatus() {
  try {
    const data=await api("getCertificateStatus",{email:session.email});
    const btn=document.getElementById("downloadCertificateBtn");
    const status=document.getElementById("certificateStatus");
    if(data.approved){ btn.disabled=false; status.textContent="Certificate approved by the authorized administrator."; status.className="status success"; }
    else { btn.disabled=true; status.textContent="Certificate is currently pending administrator approval."; status.className="status info"; }
  } catch(err) { document.getElementById("certificateStatus").textContent=err.message; }
}

async function downloadMyPerformancePdf(){
  if(!window.jspdf?.jsPDF){alert("PDF library could not be loaded.");return;}
  const data=await api("getStudentPerformance",{email:session.email});
  const s=data.student||{}, results=data.results||[], attendance=data.attendance||{};
  const {jsPDF}=window.jspdf, doc=new jsPDF({unit:"mm",format:"a4"});
  doc.setFillColor(65,32,160); doc.rect(0,0,210,30,"F");
  try{doc.addImage(document.querySelector('.brand img'),'JPEG',14,6,18,18);}catch(e){}
  doc.setTextColor(255,255,255); doc.setFontSize(16); doc.text("V.V.P.I.E.T. SOLAPUR",105,12,{align:"center"}); doc.setFontSize(11); doc.text("PYTHON BOOT CAMP - PERFORMANCE REPORT",105,21,{align:"center"});
  doc.setTextColor(25,25,25); let y=40; doc.setFontSize(12); doc.setFont(undefined,'bold'); doc.text('Student Details',15,y); y+=8; doc.setFont(undefined,'normal'); doc.setFontSize(10);
  [["Name",s.name],["Email",s.email],["Class",s.className],["Department",s.department],["Academic Year",s.academicYear]].forEach(([k,v])=>{doc.text(`${k}: ${v||'-'}`,18,y);y+=6;});
  y+=4; doc.setFont(undefined,'bold'); doc.text('Test Performance',15,y); y+=8; doc.setFont(undefined,'normal');
  results.forEach(r=>{doc.text(`${r.testName||'Test'}: ${r.score}/${r.maxScore} (${r.percentage||0}%)`,18,y);y+=6;});
  const total=results.reduce((a,r)=>a+Number(r.score||0),0), max=results.reduce((a,r)=>a+Number(r.maxScore||0),0); y+=3; doc.setFont(undefined,'bold'); doc.text(`Overall: ${total}/${max} - ${max?((total/max)*100).toFixed(2):'0.00'}%`,18,y); y+=10;
  const a=Array.isArray(attendance)?attendance:[]; const present=a.filter(x=>String(x.status).toLowerCase()==='present').length; doc.text(`Attendance: ${present}/${a.length} (${a.length?((present/a.length)*100).toFixed(2):'0.00'}%)`,18,y);
  doc.save(`Boot_Camp_Performance_${(s.name||'Student').replace(/[^a-z0-9]+/gi,'_')}.pdf`);
}

async function imageToDataUrl(path) {
  // Load the logo as real image bytes before passing it to jsPDF.
  // Passing a plain file path to addImage can create a corrupt PDF with
  // zero-width/zero-height image objects in some PDF readers (including Acrobat).
  const response = await fetch(path, { cache: "no-store" });
  if (!response.ok) throw new Error(`Could not load ${path}`);
  const blob = await response.blob();
  return await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const mime = blob.type || (path.toLowerCase().endsWith(".png") ? "image/png" : "image/jpeg");
      resolve({ data: reader.result, type: mime.includes("png") ? "PNG" : "JPEG" });
    };
    reader.onerror = () => reject(new Error(`Could not read ${path}`));
    reader.readAsDataURL(blob);
  });
}

async function downloadCertificate(){
  const status=await api('getCertificateStatus',{email:session.email});
  if(!status.approved){alert('Certificate is not approved by the authorized administrator yet.');return;}
  if(!window.jspdf?.jsPDF){alert('PDF library could not be loaded.');return;}
  const data=await api('getStudentPerformance',{email:session.email});
  const s=data.student||{};
  const {jsPDF}=window.jspdf;
  const doc=new jsPDF({unit:'mm',format:'a4'});

  // New certificate design. Logos are embedded in this file, so certificate
  // generation does not depend on local image paths or the web server.
  const collegeLogo = { data: EMBEDDED_COLLEGE_LOGO, type: 'JPEG' };
  const pythonLogo = { data: EMBEDDED_PYTHON_LOGO, type: 'PNG' };

  // Deep background and geometric frame.
  doc.setFillColor(248,250,255); doc.rect(0,0,210,297,'F');
  doc.setFillColor(23,18,91); doc.rect(0,0,210,42,'F');
  doc.setFillColor(39,42,183); doc.triangle(0,42,210,18,210,42,'F');
  doc.setFillColor(65,32,160); doc.triangle(0,42,0,58,210,42,'F');

  // Geometric outer frame.
  doc.setDrawColor(23,18,91); doc.setLineWidth(1.8); doc.rect(7,7,196,283);
  doc.setDrawColor(65,32,160); doc.setLineWidth(.6); doc.rect(11,11,188,275);
  doc.setDrawColor(39,42,183); doc.setLineWidth(.35); doc.rect(15,15,180,267);

  // Corner diamond ornaments.
  const diamonds=[[15,15],[195,15],[15,282],[195,282]];
  doc.setFillColor(39,42,183);
  diamonds.forEach(([x,y])=>{doc.line(x-4,y,x,y-4);doc.line(x,y-4,x+4,y);doc.line(x+4,y,x,y+4);doc.line(x,y+4,x-4,y);doc.circle(x,y,1.2,'F');});

  // Supplied logos.
  try { doc.addImage(collegeLogo.data,collegeLogo.type,18,20,30,30); } catch(e) {}
  try { doc.addImage(pythonLogo.data,pythonLogo.type,162,21,30,28); } catch(e) {}

  doc.setTextColor(255,255,255); doc.setFont('helvetica','bold'); doc.setFontSize(15);
  doc.text('V.V.P.I.E.T. SOLAPUR',105,20,{align:'center'});
  doc.setFontSize(8); doc.setFont('helvetica','normal'); doc.text('VVP INSTITUTES • PYTHON BOOT CAMP',105,28,{align:'center'});
  doc.setFontSize(7); doc.text('CODE • LEARN • BUILD',105,34,{align:'center'});

  // Central title block.
  doc.setTextColor(23,18,91); doc.setFont('helvetica','bold'); doc.setFontSize(10);
  doc.text('CERTIFICATE',105,70,{align:'center'});
  doc.setTextColor(39,42,183); doc.setFontSize(27); doc.text('OF COMPLETION',105,83,{align:'center'});
  doc.setDrawColor(39,42,183); doc.setLineWidth(.8); doc.line(54,90,156,90);
  doc.setTextColor(85,85,85); doc.setFont('helvetica','normal'); doc.setFontSize(11);
  doc.text('This certificate is proudly presented to',105,105,{align:'center'});

  // Student name on a highlighted nameplate.
  doc.setFillColor(240,242,252); doc.roundedRect(30,114,150,28,5,5,'F');
  doc.setDrawColor(65,32,160); doc.setLineWidth(.7); doc.roundedRect(30,114,150,28,5,5,'S');
  doc.setTextColor(23,18,91); doc.setFont('helvetica','bold'); doc.setFontSize(23);
  doc.text(String(s.name||'Student'),105,132,{align:'center'});

  doc.setTextColor(70,70,70); doc.setFont('helvetica','normal'); doc.setFontSize(11);
  doc.text('for successfully completing the Python Boot Camp program',105,154,{align:'center'});
  doc.setFontSize(10); doc.text(`Department: ${s.department||'-'}`,105,166,{align:'center'});
  doc.text(`Academic Year: ${s.academicYear||'-'}`,105,174,{align:'center'});

  // Certificate ID badge.
  doc.setFillColor(23,18,91); doc.roundedRect(62,184,86,14,7,7,'F');
  doc.setTextColor(255,255,255); doc.setFont('helvetica','bold'); doc.setFontSize(8);
  doc.text(`CERTIFICATE ID  ${status.certificateId||'BOOTCAMP-CERT'}`,105,193,{align:'center'});

  // Signature section with clean signature cards.
  const cards=[{x:22,label:'PRINCIPAL'},{x:79,label:'HOD'},{x:136,label:'ADMIN'}];
  cards.forEach(card=>{
    doc.setFillColor(250,250,253); doc.roundedRect(card.x,220,52,31,4,4,'F');
    doc.setDrawColor(205,208,225); doc.setLineWidth(.35); doc.roundedRect(card.x,220,52,31,4,4,'S');
    doc.setDrawColor(80,80,80); doc.setLineWidth(.35); doc.line(card.x+8,241,card.x+44,241);
    doc.setTextColor(35,35,50); doc.setFont('helvetica','bold'); doc.setFontSize(8); doc.text(card.label,card.x+26,247,{align:'center'});
    doc.setTextColor(100,100,110); doc.setFont('helvetica','italic'); doc.setFontSize(6.5); doc.text('Signature',card.x+26,235,{align:'center'});
  });

  // Approval seal — no admin email is printed.
  doc.setDrawColor(39,42,183); doc.setLineWidth(1); doc.circle(105,268,14,'S');
  doc.setDrawColor(65,32,160); doc.setLineWidth(.5); doc.circle(105,268,11,'S');
  doc.setTextColor(39,42,183); doc.setFont('helvetica','bold'); doc.setFontSize(6.5); doc.text('APPROVED',105,267,{align:'center'}); doc.setFontSize(5.5); doc.text('BOOT CAMP',105,272,{align:'center'});
  doc.setTextColor(95,95,105); doc.setFont('helvetica','normal'); doc.setFontSize(7); doc.text('Certificate issued after authorized administrative approval.',105,286,{align:'center'});

  doc.save(`Python_Boot_Camp_Certificate_${(s.name||'Student').replace(/[^a-z0-9]+/gi,'_')}.pdf`);
}
async function submitFeedback(e){
  e.preventDefault();
  const status=document.getElementById('feedbackStatus');
  const button=e.target.querySelector('button[type="submit"]');
  try{
    button.disabled=true; status.className='status info'; status.textContent='Submitting feedback…';
    const result=await api('submitFeedback',{email:session.email,rating:document.getElementById('feedbackRating').value,feedback:document.getElementById('feedbackText').value.trim()});
    status.className='status success'; status.textContent=result.message||'Feedback submitted successfully.';
    document.getElementById('feedbackText').value='';
  }catch(err){status.className='status error';status.textContent=err.message;}
  finally{button.disabled=false;}
}

async function loadResults() {
  const box = document.getElementById("results");
  box.innerHTML = `<div class="loading">Loading test results…</div>`;

  try {
    const data = await api("getStudentResults", {email: session.email});
    renderResults(data.results || []);
  } catch (err) {
    box.innerHTML = `<div class="empty error-text">${escapeHtml(err.message)}</div>`;
  }
}

function renderResults(results) {
  const box = document.getElementById("results");

  if (!results.length) {
    box.innerHTML = `<div class="empty">No test results yet.</div>`;
    return;
  }

  box.innerHTML = `
    <table>
      <thead>
        <tr>
          <th>Test</th>
          <th>Score</th>
          <th>Max</th>
          <th>Percentage</th>
          <th>Correct</th>
          <th>Wrong</th>
          <th>Date</th>
        </tr>
      </thead>
      <tbody>
        ${results.map(r => `
          <tr>
            <td>${escapeHtml(r.testName)}</td>
            <td>${Number(r.score || 0)}</td>
            <td>${Number(r.maxScore || 0)}</td>
            <td>${Number(r.percentage || 0)}%</td>
            <td>${Number(r.correct || 0)}</td>
            <td>${Number(r.wrong || 0)}</td>
            <td>${escapeHtml(r.timestamp)}</td>
          </tr>
        `).join("")}
      </tbody>
    </table>`;
}

async function loadAttendance() {
  const box = document.getElementById("studentAttendance");
  box.innerHTML = `<div class="loading">Loading attendance…</div>`;

  try {
    const data = await api("getStudentAttendance", {email: session.email});
    renderAttendance(data.attendance || [], data.summary || {});
  } catch (err) {
    box.innerHTML = `<div class="empty error-text">${escapeHtml(err.message)}</div>`;
  }
}

function renderAttendance(records, summary) {
  const summaryBox = document.getElementById("attendanceSummary");
  const box = document.getElementById("studentAttendance");

  summaryBox.innerHTML = `
    <div><b>${Number(summary.total || 0)}</b><span>Total Days</span></div>
    <div><b>${Number(summary.present || 0)}</b><span>Present</span></div>
    <div><b>${Number(summary.absent || 0)}</b><span>Absent</span></div>
    <div><b>${Number(summary.late || 0)}</b><span>Late</span></div>
    <div><b>${Number(summary.percentage || 0)}%</b><span>Attendance</span></div>
  `;

  if (!records.length) {
    box.innerHTML = `<div class="empty">No attendance records yet.</div>`;
    return;
  }

  box.innerHTML = `
    <table>
      <thead>
        <tr>
          <th>Date</th>
          <th>Status</th>
        </tr>
      </thead>
      <tbody>
        ${records.map(a => `
          <tr>
            <td>${escapeHtml(a.date)}</td>
            <td><span class="pill attendance-${escapeHtml(String(a.status).toLowerCase())}">${escapeHtml(a.status)}</span></td>
          </tr>
        `).join("")}
      </tbody>
    </table>`;
}


// Download the logged-in student's profile, attendance and test results as CSV.
async function downloadMyPerformance() {
  const button = document.getElementById("downloadPerformanceBtn");
  if (!button) return;

  button.disabled = true;
  button.textContent = "Preparing…";

  try {
    const data = await api("getStudentPerformance", {email: session.email});
    const rows = [["Student Performance Report"], []];

    rows.push(["Name", data.student.name]);
    rows.push(["Email", data.student.email]);
    rows.push(["Class", data.student.className || ""]);
    rows.push(["Roll", data.student.roll || ""]);
    rows.push(["Department", data.student.department || ""]);
    rows.push(["Academic Year", data.student.academicYear || ""]);
    rows.push([]);

    rows.push(["TEST RESULTS"]);
    rows.push(["Test", "Score", "Max Score", "Percentage", "Correct", "Wrong", "Date"]);
    (data.results || []).forEach(r => rows.push([
      r.testName, r.score, r.maxScore, r.percentage + "%", r.correct, r.wrong, r.timestamp
    ]));

    rows.push([]);
    rows.push(["ATTENDANCE"]);
    rows.push(["Date", "Status"]);
    (data.attendance || []).forEach(a => rows.push([a.date, a.status]));

    downloadCsv(rows, "my_boot_camp_performance.csv");
  } catch (err) {
    alert(err.message);
  } finally {
    button.disabled = false;
    button.textContent = "Download My Performance";
  }
}

function downloadCsv(rows, filename) {
  const csv = rows.map(row => row.map(csvCell).join(",")).join("\r\n");
  const blob = new Blob(["\ufeff" + csv], {type:"text/csv;charset=utf-8;"});
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function csvCell(value) {
  const text = String(value ?? "");
  return '"' + text.replace(/"/g, '""') + '"';
}
